package com.amalaei.engineering;
import android.content.Context;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.text.*;import org.json.*;import java.math.*;import java.io.*;
final class Quotation {
 static JSONObject company()throws Exception{return new JSONObject().put("name","").put("registration","").put("vat","").put("address","").put("phone","").put("email","");}

 static BigDecimal subtotal(JSONObject q)throws Exception{BigDecimal sum=BigDecimal.ZERO;JSONArray items=q.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject a=items.getJSONObject(i);sum=sum.add(QuoteMath.line(a.getString("qty"),a.getString("price")));}return sum;}
 static void validate(JSONObject q)throws Exception{if(!q.optString("business","survey").equals("survey"))throw new IllegalArgumentException("النموذج خاص بالمساحة");if(q.optString("customer").trim().isEmpty()||q.optString("number").trim().isEmpty())throw new IllegalArgumentException("أدخل العميل ورقم العرض");for(String key:new String[]{"customer","number","customerVat","customerPhone","customerAddress"})if(q.optString(key).length()>(key.equals("customerAddress")?110:80))throw new IllegalArgumentException("اختصر بيانات العميل لتناسب النموذج");java.time.LocalDate.parse(q.getString("date"));JSONArray items=q.getJSONArray("items");if(items.length()<1||items.length()>100)throw new IllegalArgumentException("أضف من صنف إلى 100 صنف");for(int i=0;i<items.length();i++)if(items.getJSONObject(i).optString("description").trim().isEmpty()||items.getJSONObject(i).optString("description").length()>80||items.getJSONObject(i).optString("unit").length()>15)throw new IllegalArgumentException("أدخل وصف كل صنف");subtotal(q);JSONObject c=q.getJSONObject("company");if(c.optString("name").isEmpty())throw new IllegalArgumentException("أدخل اسم المنشأة");}
 static final int BLUE=0xff294f96,GRAY=0xff646b76;static final float[] X={34,117,204,257,311,529,562};
 static void txt(Canvas canvas,Typeface font,String text,float x,float y,int width,float size,int color,boolean center){TextPaint p=new TextPaint(3);p.setTypeface(font);p.setTextSize(size);p.setColor(color);StaticLayout l=StaticLayout.Builder.obtain(text,0,text.length(),p,width).setAlignment(center?Layout.Alignment.ALIGN_CENTER:Layout.Alignment.ALIGN_NORMAL).setTextDirection(TextDirectionHeuristics.FIRSTSTRONG_RTL).setIncludePad(false).build();canvas.save();canvas.translate(x,y);l.draw(canvas);canvas.restore();}
 static void rect(Canvas c,float l,float t,float r,float b,int color){Paint p=new Paint();p.setColor(color);c.drawRect(l,t,r,b,p);}static void line(Canvas c,float x,float y,float r,int color){rect(c,x,y,r,y+0.6f,color);}
 static File pdf(Context ctx,JSONObject q)throws Exception{validate(q);PdfDocument doc=new PdfDocument();Typeface font=Typeface.createFromAsset(ctx.getAssets(),"fonts/Cairo.ttf");JSONArray items=q.getJSONArray("items");int pages=(items.length()+5)/6;JSONObject co=q.getJSONObject("company");try{for(int page=0;page<pages;page++){PdfDocument.Page p=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,page+1).create());Canvas c=p.getCanvas();c.drawColor(Color.WHITE);txt(c,font,co.optString("name"),60,23,400,17,0xffb90000,true);txt(c,font,"السجل التجاري: "+co.optString("registration"),80,51,370,10,GRAY,true);txt(c,font,"الرقم الضريبي: "+co.optString("vat"),80,66,370,10,GRAY,true);line(c,34,84,562,BLUE);txt(c,font,"عرض سعر مبيعات",34,91,528,17,BLUE,true);rect(c,34,113,562,134,0xfff4f5f7);String date=java.time.LocalDate.parse(q.getString("date")).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"));txt(c,font,q.getString("number")+" · "+date,34,116,528,10,GRAY,true);txt(c,font,"رقم العرض: "+q.getString("number"),34,146,528,11,GRAY,false);txt(c,font,"تاريخ العرض: "+date,34,163,528,11,GRAY,false);rect(c,34,188,562,278,0xfff8f9fb);txt(c,font,"بيانات العرض",45,194,505,12,BLUE,false);txt(c,font,"العميل: "+q.getString("customer"),45,216,505,11,GRAY,false);txt(c,font,"الرقم الضريبي: "+q.optString("customerVat")+"   •   الهاتف: "+q.optString("customerPhone"),45,236,505,9,GRAY,false);txt(c,font,"العنوان الوطني: "+q.optString("customerAddress"),45,253,505,9,GRAY,false);line(c,45,273,550,0xffd6deea);float y=291;rect(c,34,y,562,y+24,BLUE);String[] h={"المبلغ","سعر الوحدة","الكمية","الوحدة","الوصف","م"};for(int col=0;col<6;col++)txt(c,font,h[col],X[col]+2,y+5,(int)(X[col+1]-X[col]-4),10,Color.WHITE,true);y+=24;for(int n=page*6;n<Math.min(items.length(),(page+1)*6);n++){JSONObject a=items.getJSONObject(n);String[] values={QuoteMath.money(QuoteMath.line(a.getString("qty"),a.getString("price"))),QuoteMath.money(QuoteMath.number(a.getString("price"))),QuoteMath.money(QuoteMath.number(a.getString("qty"))),a.optString("unit","—"),a.getString("description"),String.valueOf(n+1)};float height=52;for(int col=0;col<6;col++){rect(c,X[col],y,X[col+1],y+height,0xffe0e5ee);rect(c,X[col]+.5f,y+.5f,X[col+1]-.5f,y+height-.5f,Color.WHITE);txt(c,font,values[col],X[col]+3,y+5,(int)(X[col+1]-X[col]-6),col==4?10:9,GRAY,true);}y+=height;}if(page==pages-1){y+=16;BigDecimal sub=subtotal(q),tax=QuoteMath.tax(sub);rect(c,276,y,562,y+79,0xfff8f9fb);String[] labels={"المجموع الفرعي","الضريبة","الإجمالي"};BigDecimal[] v={sub,tax,sub.add(tax)};for(int n=0;n<3;n++){txt(c,font,labels[n],425,y+5+n*25,126,11,n==2?BLUE:GRAY,false);txt(c,font,QuoteMath.money(v[n])+" SAR",286,y+5+n*25,136,11,n==2?BLUE:GRAY,true);}line(c,286,y+49,551,BLUE);y+=98;}else y+=20;line(c,34,y,562,BLUE);txt(c,font,co.optString("address"),34,y+8,528,11,BLUE,true);txt(c,font,"هاتف: "+co.optString("phone")+" · "+co.optString("email"),34,y+28,528,10,0xff398e98,true);txt(c,font,"صفحة "+(page+1)+" من "+pages,34,y+46,528,10,0xff398e98,true);doc.finishPage(p);}File f=new File(ctx.getCacheDir(),"quote-"+java.util.UUID.randomUUID().toString().replace("-","")+".pdf");try(OutputStream out=new FileOutputStream(f)){doc.writeTo(out);}return f;}finally{doc.close();}}
}
